-- MYFITDAILY - Full Database Schema & Seed Data for Supabase PostgreSQL
-- Production Ready & Synchronized with DbSeeder

CREATE TABLE IF NOT EXISTS "__EFMigrationsHistory" (
    "MigrationId" character varying(150) NOT NULL,
    "ProductVersion" character varying(32) NOT NULL,
    CONSTRAINT "PK___EFMigrationsHistory" PRIMARY KEY ("MigrationId")
);

START TRANSACTION;

-- 1. CATEGORIES TABLE
CREATE TABLE IF NOT EXISTS "Categories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Name" character varying(50) NOT NULL,
    "Description" character varying(250),
    "DisplayOrder" integer NOT NULL,
    "IsActive" boolean NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Categories" PRIMARY KEY ("Id")
);

-- 2. USERS TABLE
CREATE TABLE IF NOT EXISTS "Users" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "Email" character varying(100) NOT NULL,
    "PasswordHash" text NOT NULL,
    "FullName" character varying(100) NOT NULL,
    "AvatarUrl" character varying(500),
    "Gender" character varying(20),
    "Role" character varying(20) NOT NULL DEFAULT 'User',
    "SubscriptionType" character varying(20) NOT NULL DEFAULT 'Free',
    "Height" double precision,
    "Weight" double precision,
    "Chest" double precision,
    "Waist" double precision,
    "Hips" double precision,
    "BodyShape" character varying(50),
    "Age" integer,
    "AgeGroup" character varying(50),
    "SubscriptionExpiresAt" timestamp with time zone,
    "SubscriptionPeriod" character varying(20),
    "TotalUsageSeconds" bigint DEFAULT 0,
    "LongestSessionSeconds" bigint DEFAULT 0,
    "PrimaryFeature" character varying(100),
    "FeatureUsageJson" text,
    "LastActiveAt" timestamp with time zone,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Users" PRIMARY KEY ("Id")
);

-- 3. AI STYLIST HISTORIES TABLE
CREATE TABLE IF NOT EXISTS "AiStylistHistories" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Occasion" character varying(50),
    "Style" character varying(50),
    "Weather" character varying(50),
    "RecommendedOutfitData" text NOT NULL,
    "FeedbackRating" integer,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_AiStylistHistories" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_AiStylistHistories_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

-- 4. CLOTHING ITEMS TABLE
CREATE TABLE IF NOT EXISTS "ClothingItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "CategoryId" integer NOT NULL,
    "Name" character varying(100) NOT NULL,
    "Color" character varying(50) NOT NULL,
    "Style" character varying(50) NOT NULL,
    "Season" character varying(50) NOT NULL,
    "ImageUrl" text NOT NULL,
    "Description" text,
    "Brand" character varying(100),
    "Size" character varying(20),
    "Price" numeric,
    "PriceFormatted" character varying(50),
    "AffiliateUrl" text,
    "OriginalUrl" text,
    "Platform" character varying(50),
    "IsAffiliate" boolean NOT NULL DEFAULT false,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_ClothingItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_ClothingItems_Categories_CategoryId" FOREIGN KEY ("CategoryId") REFERENCES "Categories" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_ClothingItems_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

-- 5. OUTFITS TABLE
CREATE TABLE IF NOT EXISTS "Outfits" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer NOT NULL,
    "Name" character varying(100) NOT NULL,
    "Description" character varying(500),
    "Occasion" character varying(50),
    "Season" character varying(50),
    "IsFavorite" boolean NOT NULL DEFAULT false,
    "CreatedByAi" boolean NOT NULL DEFAULT false,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_Outfits" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_Outfits_Users_UserId" FOREIGN KEY ("UserId") REFERENCES "Users" ("Id") ON DELETE CASCADE
);

-- 6. OUTFIT ITEMS LINK TABLE
CREATE TABLE IF NOT EXISTS "OutfitItems" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "OutfitId" integer NOT NULL,
    "ClothingItemId" integer NOT NULL,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone,
    CONSTRAINT "PK_OutfitItems" PRIMARY KEY ("Id"),
    CONSTRAINT "FK_OutfitItems_ClothingItems_ClothingItemId" FOREIGN KEY ("ClothingItemId") REFERENCES "ClothingItems" ("Id") ON DELETE RESTRICT,
    CONSTRAINT "FK_OutfitItems_Outfits_OutfitId" FOREIGN KEY ("OutfitId") REFERENCES "Outfits" ("Id") ON DELETE CASCADE
);

-- 7. PAYMENT TRANSACTIONS TABLE (SEPAY INTEGRATION)
CREATE TABLE IF NOT EXISTS "PaymentTransactions" (
    "Id" integer GENERATED BY DEFAULT AS IDENTITY,
    "UserId" integer,
    "OrderCode" character varying(50),
    "PlanId" character varying(50),
    "BillingCycle" character varying(20),
    "Amount" numeric,
    "Status" character varying(30) DEFAULT 'Pending',
    "SePayTransactionId" character varying(100),
    "PaidAt" timestamp with time zone,
    "BankBrandName" character varying(50),
    "AccountNumber" character varying(50),
    "TransactionContent" text,
    "CreatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    "UpdatedAt" timestamp with time zone NOT NULL DEFAULT NOW(),
    CONSTRAINT "PK_PaymentTransactions" PRIMARY KEY ("Id")
);
CREATE UNIQUE INDEX IF NOT EXISTS "IX_PaymentTransactions_OrderCode" ON "PaymentTransactions" ("OrderCode");

